import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const [h, w] = input[0].split(" ").map(Number);

// dp[x] = 今の行の x 列目にたどり着く最小コスト
const dp = new Array(w).fill(Infinity);
for (let y = 0; y < h; y++) {
  const row = input[y + 1].split(" ").map(Number);
  for (let x = 0; x < w; x++) {
    if (y === 0 && x === 0) {
      dp[x] = row[x];
      continue;
    }
    const fromLeft = x > 0 ? dp[x - 1] : Infinity;
    dp[x] = Math.min(dp[x], fromLeft) + row[x]; // dp[x] は上から来た場合
  }
}
console.log(dp[w - 1]);
